// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 100 ether);
        GasConsumer gc = new GasConsumer();
        vm.deal(address(c), 100 ether);
        vm.prank(c.owner());
        c.sendMoney(address(gc), amount);
        assertEq(gc.received(), true);
    }
}

contract GasConsumer {
    bool public received;
    receive() external payable {
        uint256 x;
        for (uint256 i = 0; i < 100; i++) {
            x++;
        }
        received = true;
    }
}
